+      // Trussbars AOT-compat: does this MaxBars template build under the Trussbars
+      // production AOT compiler? The structural verdict is the real AOT front-end's
+      // (drift-proof); numeric-truthiness / struct-output are observed against the
+      // sample data. Advisory — MaxBars and the Trussbars VM still run it; only the
+      // AOT (max-speed) backend rejects it.
+      const COMPAT_RULE_LABEL = {
+        "aot-structural": "structural",
+        "numeric-truthiness": "numeric truthiness",
+        "struct-output": "struct output",
+      };
+      function renderTrussbarsCompat(body) {
+        const a = lastCompat;
+        const section = makeEl("div", { class: "cv-section" });
+        const plain = (s) => String(s).replace(/`/g, "");
+        if (!a.ok) {
+          section.append(makeEl("div", { class: "cv-empty" },
+            "Compatibility unavailable: " + (a.error || "the template did not parse.")));
+          body.append(section);
+          return;
+        }
+        const rows = a.findings;
+        section.append(makeEl("div", { class: "cv-head" }, [
+          makeEl("strong", {}, "Trussbars AOT"),
+          " — ",
+          a.compatible ? "compatible" : `${rows.length} incompatibilit${rows.length === 1 ? "y" : "ies"}`,
+        ]));
+        if (a.compatible) {
+          section.append(makeEl("div", { class: "cv-empty" },
+            "This template compiles under the Trussbars production AOT compiler — names are static, data is dynamic, the two never cross."));
+          body.append(section);
+          return;
+        }
+        section.append(makeEl("div", { class: "cv-hint" },
+          "These render fine under MaxBars (and the Trussbars VM), but the typed AOT backend rejects them. The VM backend runs them unchanged."));
+        const list = makeEl("div", { class: "cv-rows" });
+        for (const f of rows) {
+          const row = makeEl("div", { class: "cv-row" }, [
+            makeEl("span", { class: "cv-kind" }, COMPAT_RULE_LABEL[f.rule] || f.rule),
+            makeEl("span", { class: "cv-label" }, plain(f.message)),
+            makeEl("span", { class: "cv-where" }, `main:${f.line}:${f.column}`),
+          ]);
+          row.title = "jump to source";
+          row.addEventListener("click", () => openProblem({ file: "main", line: f.line, col: f.column }));
+          list.append(row);
+        }
+        section.append(list);
+        body.append(section);
+      }
